import{_ as r,o as t,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Re-Architecting Ceph, One Crimson-OSD at a Time - Matan Breizman, IBM","description":"","frontmatter":{"title":"Re-Architecting Ceph, One Crimson-OSD at a Time - Matan Breizman, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","Crimson 项目","分布式存储","性能优化","存储架构"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Re-Architecting_Ceph_One_Crimson-OSD_at_a_Time_-_Matan_Breizman_IBM.md","filePath":"posts/2025/Re-Architecting_Ceph_One_Crimson-OSD_at_a_Time_-_Matan_Breizman_IBM.md","lastUpdated":1780459816000}'),e={name:"posts/2025/Re-Architecting_Ceph_One_Crimson-OSD_at_a_Time_-_Matan_Breizman_IBM.md"};function i(s,a,l,h,g,_){return t(),o("div",null,[...a[0]||(a[0]=[n('<h3 id="ceph-crimson项目进展会议纪要" tabindex="-1"><strong>Ceph Crimson项目进展会议纪要</strong> <a class="header-anchor" href="#ceph-crimson项目进展会议纪要" aria-label="Permalink to &quot;**Ceph Crimson项目进展会议纪要**&quot;">​</a></h3><h4 id="会议概述" tabindex="-1"><strong>会议概述</strong> <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;**会议概述**&quot;">​</a></h4><p>本次会议由Ceph核心开发团队成员Matan主持，重点介绍了Crimson项目的背景、目标、当前进展及未来规划。Crimson项目旨在通过重构Ceph的OSD（对象存储守护进程）来提升性能，特别是在多核CPU和NVMe SSD等现代存储设备上的表现。</p><h4 id="关键讨论议题" tabindex="-1"><strong>关键讨论议题</strong> <a class="header-anchor" href="#关键讨论议题" aria-label="Permalink to &quot;**关键讨论议题**&quot;">​</a></h4><h5 id="_1-crimson项目的背景与动机" tabindex="-1"><strong>1. Crimson项目的背景与动机</strong> <a class="header-anchor" href="#_1-crimson项目的背景与动机" aria-label="Permalink to &quot;**1. Crimson项目的背景与动机**&quot;">​</a></h5><ul><li><strong>CPU架构趋势</strong>：自2008年以来，CPU核心数大幅增加，但时钟频率趋于稳定，因此并发性成为提升性能的关键。</li><li><strong>现有Classical OSD的瓶颈</strong>：多线程架构导致高锁争用、频繁上下文切换和CPU缓存局部性差，影响性能。</li></ul><h5 id="_2-crimson架构的核心改进" tabindex="-1"><strong>2. Crimson架构的核心改进</strong> <a class="header-anchor" href="#_2-crimson架构的核心改进" aria-label="Permalink to &quot;**2. Crimson架构的核心改进**&quot;">​</a></h5><ul><li><strong>共享无状态设计</strong>：每个核心拥有一个线程，通过SeaStar框架实现无锁化，提高数据局部性和CPU利用率。</li><li><strong>技术挑战与解决方案</strong>：采用C++20协程简化异步代码，引入<code>errorator</code>机制强制编译期错误检查，提升调试体验。</li></ul><h5 id="_3-性能对比与测试结果" tabindex="-1"><strong>3. 性能对比与测试结果</strong> <a class="header-anchor" href="#_3-性能对比与测试结果" aria-label="Permalink to &quot;**3. 性能对比与测试结果**&quot;">​</a></h5><ul><li><strong>Perf工具分析</strong>：Crimson OSD在上下文切换、CPU迁移、低利用率和缓存命中率方面优于Classical OSD。</li><li><strong>IOPS与延迟测试</strong>：Crimson在随机读性能上达到Classical的4倍以上，但在随机写性能上仍有提升空间。</li></ul><h5 id="_4-项目进展与roadmap" tabindex="-1"><strong>4. 项目进展与Roadmap</strong> <a class="header-anchor" href="#_4-项目进展与roadmap" aria-label="Permalink to &quot;**4. 项目进展与Roadmap**&quot;">​</a></h5><ul><li><strong>已实现功能</strong>：Squid版本支持BlueStore后端、多核并发、PG分裂；Tentacle版本提供Systo后端技术预览和性能优化。</li><li><strong>Umbrella版本计划</strong>：Seamless部署、RGW支持、FastEC、Scrub调度、PG合并以支持Autoscaler。</li><li><strong>未来方向</strong>：验证混合集群可行性，持续优化随机写性能。</li></ul><h5 id="行动计划与待办事项" tabindex="-1"><strong>行动计划与待办事项</strong> <a class="header-anchor" href="#行动计划与待办事项" aria-label="Permalink to &quot;**行动计划与待办事项**&quot;">​</a></h5><ul><li><strong>性能优化</strong>：提升随机写性能，扩展FastEC支持至Crimson。</li><li><strong>功能完善</strong>：完成Systo的完整恢复能力，更新用户文档。</li><li><strong>测试与反馈</strong>：扩大夜间测试覆盖范围，邀请社区参与早期部署测试。</li><li><strong>社区协作</strong>：鼓励贡献者加入，特别感谢Joy Han和Yingen对Systo的贡献。</li></ul><h4 id="问答环节摘要" tabindex="-1"><strong>问答环节摘要</strong> <a class="header-anchor" href="#问答环节摘要" aria-label="Permalink to &quot;**问答环节摘要**&quot;">​</a></h4><ul><li><strong>Q</strong>：随机读写测试是否支持EC（Erasure Coding）？ <ul><li><strong>A</strong>：当前仅支持副本（replication），FastEC将在未来支持。</li></ul></li><li><strong>Q</strong>：Crimson何时达到功能完备？ <ul><li><strong>A</strong>：Umbrella版本后可作为技术预览，但生产环境需待关键功能稳定。</li></ul></li><li><strong>Q</strong>：新增监控指标？ <ul><li><strong>A</strong>：新增Crimson专属指标，如reactor利用率、冲突事件统计。</li></ul></li></ul><h4 id="总结" tabindex="-1"><strong>总结</strong> <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;**总结**&quot;">​</a></h4><p>Crimson项目通过架构革新显著提升了Ceph在多核环境下的性能，尤其在随机读场景表现突出。下一步将聚焦随机写优化、生态兼容性及用户体验，并呼吁社区参与测试，共同推动项目成熟。</p>',18)])])}const d=r(e,[["render",i]]);export{c as __pageData,d as default};
